import {HEROES} from './simulation.mjs?v=20261030-duel12';
import {defaultDuelLoadout,validateDuelLoadout,duelSkillChoices} from './duel-skill-data.mjs';
import {renderDuelSkillChoices,renderDuelSkillSlots} from './duel-skill-ui.mjs';
export class PracticeDialog{
 constructor({onConfirm,onClose=()=>{}}){this.onConfirm=onConfirm;this.onClose=onClose;this.el=document.createElement('dialog');this.el.className='practice-dialog';this.el.innerHTML='<form method="dialog"><button class="practice-close" aria-label="关闭试玩搭配">×</button></form><header><small>HERO TRIAL · SIX ARTS</small><h2></h2><p>每行选择一个招式 · 全部免费试玩</p></header><div class="practice-choices"></div><footer><div class="practice-slots"></div><label>试炼场景<select aria-label="试玩场景"><option value="moon">月光遗迹</option><option value="lava">熔岩祭坛</option><option value="garden">浮空花园</option></select></label><button type="button" class="practice-confirm">进入试玩 ›</button></footer>';
 document.body.append(this.el);this.el.addEventListener('close',()=>this.onClose());this.el.querySelector('.practice-confirm').addEventListener('click',()=>{const selection={hero:this.hero,loadout:validateDuelLoadout(this.hero,this.loadout),scene:this.el.querySelector('select').value};this.el.close();this.onConfirm(selection);});this.el.addEventListener('click',e=>{const button=e.target.closest('[data-pick-skill]');if(!button)return;const s=duelSkillChoices(this.hero).find(s=>s.id===button.dataset.pickSkill);if(s){this.loadout[s.key]=s.id;this.render();this.el.querySelector(`[data-pick-skill="${s.id}"]`).focus();}});}
 get isOpen(){return this.el.open;}
 open(hero,loadout=defaultDuelLoadout(hero),scene='moon',inTrial=false){this.hero=hero;this.loadout={...validateDuelLoadout(hero,loadout)};this.el.querySelector('select').value=scene;this.el.querySelector('.practice-confirm').textContent=inTrial?'应用搭配 · 继续试玩 ›':'进入试玩 ›';this.render();this.el.showModal();}
 render(){this.el.querySelector('h2').textContent=HEROES[this.hero].name+' · 技能搭配';this.el.querySelector('.practice-choices').innerHTML=renderDuelSkillChoices(this.hero,this.loadout,HEROES[this.hero].skills);this.el.querySelector('.practice-slots').innerHTML=renderDuelSkillSlots(this.hero,this.loadout);}
}
